import {
  forwardRef,
  useCallback,
  useEffect,
  useImperativeHandle,
  useRef,
  type HTMLAttributes,
} from "react";
import { cn } from "@/lib/utils";

const VERTEX_SHADER = `
attribute vec2 aPosition;

void main() {
  gl_Position = vec4(aPosition, 0.0, 1.0);
}
`;

const FRAGMENT_SHADER = `
precision mediump float;

uniform vec2 uResolution;
uniform float uTime;
uniform float uProgress;
uniform float uOpacity;
uniform float uVertical;
uniform float uReverse;
uniform float uBandSize;
uniform float uIntensity;
uniform float uRipple;
uniform vec3 uColorA;
uniform vec3 uColorB;
uniform vec3 uColorC;

vec3 threeStopGradient(float t) {
  float firstHalf = smoothstep(0.0, 0.5, t);
  float secondHalf = smoothstep(0.5, 1.0, t);
  vec3 firstMix = mix(uColorA, uColorB, firstHalf);
  return mix(firstMix, uColorC, secondHalf);
}

void main() {
  vec2 uv = gl_FragCoord.xy / uResolution;
  float axis = mix(uv.x, uv.y, uVertical);
  float crossAxis = mix(uv.y, uv.x, uVertical);

  float forwardPosition = mix(-0.16, 1.16, uProgress);
  float reversePosition = mix(1.16, -0.16, uProgress);
  float position = mix(forwardPosition, reversePosition, uReverse);

  float ripple =
    sin(crossAxis * 5.2 + uTime * 0.55) * 0.010 +
    sin(crossAxis * 13.0 - uTime * 0.32 + 1.7) * 0.004;
  float distanceToBand = axis - position - ripple * uRipple;
  float normalizedDistance = distanceToBand / max(0.035, uBandSize);

  float core = exp(-normalizedDistance * normalizedDistance * 1.85);
  float atmosphere = exp(-abs(normalizedDistance) * 1.15) * 0.32;
  float presence = max(core, atmosphere);

  float colorPosition = clamp(
    0.5 + normalizedDistance * 0.18 + crossAxis * 0.18 + sin(uTime * 0.32) * 0.025,
    0.0,
    1.0
  );
  vec3 color = threeStopGradient(colorPosition);

  float crest = pow(core, 5.0);
  color += vec3(0.20) * crest;

  float entry = smoothstep(0.0, 0.10, uProgress);
  float alpha = clamp(presence * uOpacity * uIntensity * entry, 0.0, 1.0);
  gl_FragColor = vec4(color * alpha, alpha);
}
`;

const SHADER_SWEEP_PALETTES = {
  aurora: ["#19d3c5", "#6967ff", "#ef4fae"],
  rose: ["#ff7657", "#f43f75", "#8d4bff"],
  tide: ["#176bff", "#22c9e8", "#73e46b"],
  solar: ["#9ee93a", "#ffd23f", "#ff6b35"],
  ember: ["#ffd166", "#ff7a38", "#ed315d"],
} as const;

type ShaderSweepPaletteName = keyof typeof SHADER_SWEEP_PALETTES;
type ShaderSweepPalette = readonly [string, string, string];
type ShaderSweepDirection = "left" | "right" | "up" | "down";
type ShaderSweepEasing = "linear" | "ease-out" | "ease-in-out" | ((progress: number) => number);
type ShaderSweepPosition = "fixed" | "absolute";

interface ShaderSweepPlayOptions {
  /** Three-stop preset or a custom tuple of hex colors. */
  palette?: ShaderSweepPaletteName | ShaderSweepPalette;
  /** Direction the band travels across the canvas. */
  direction?: ShaderSweepDirection;
  /** Band traversal time in milliseconds. */
  duration?: number;
  /** Fade time after the band reaches the far edge. */
  fadeDuration?: number;
  /** Progress point (0–1) at which onMidpoint runs. */
  midpoint?: number;
  /** Normalized band width. Lower values create a tighter beam. */
  bandSize?: number;
  /** Alpha and brightness multiplier. */
  intensity?: number;
  /** Edge displacement amount. Set to 0 for a straight band. */
  ripple?: number;
  /** Motion curve for the traversal. */
  easing?: ShaderSweepEasing;
  /** Runs once the sweep reaches midpoint. Use it to swap the underlying view. */
  onMidpoint?: () => void | Promise<void>;
  /** Runs after the band finishes and fades away. */
  onComplete?: () => void;
}

interface ShaderSweepPlayback {
  /** Resolves after onMidpoint finishes. */
  midpoint: Promise<void>;
  /** Resolves when the sweep and fade are complete. */
  finished: Promise<void>;
  /** Stops the active sweep and clears the canvas. */
  cancel: () => void;
}

interface ShaderSweepHandle {
  play: (options?: ShaderSweepPlayOptions) => ShaderSweepPlayback;
  cancel: () => void;
}

interface ShaderSweepProps
  extends
    Omit<HTMLAttributes<HTMLCanvasElement>, "children" | "onAnimationStart">,
    ShaderSweepPlayOptions {
  /** "fixed" covers the viewport; "absolute" fills the nearest positioned parent. */
  position?: ShaderSweepPosition;
  /** Stacking order for the canvas. */
  zIndex?: number;
  /** "skip" honors prefers-reduced-motion; "animate" forces the shader sweep. */
  reducedMotion?: "skip" | "animate";
}

type Rgb = readonly [number, number, number];
type ResolvedPalette = readonly [Rgb, Rgb, Rgb];

interface ShaderFrame {
  progress: number;
  opacity: number;
  time: number;
  vertical: number;
  reverse: number;
  bandSize: number;
  intensity: number;
  ripple: number;
  palette: ResolvedPalette;
}

interface ShaderRenderer {
  render: (frame: ShaderFrame) => void;
  clear: () => void;
  destroy: () => void;
}

interface Deferred {
  promise: Promise<void>;
  resolve: () => void;
}

const DEFAULT_OPTIONS = {
  palette: "aurora" as const,
  direction: "right" as const,
  duration: 900,
  fadeDuration: 300,
  midpoint: 0.52,
  bandSize: 0.18,
  intensity: 1,
  ripple: 0.45,
  easing: "ease-in-out" as const,
};

function clamp(value: number, min: number, max: number) {
  return Math.min(max, Math.max(min, value));
}

function createDeferred(): Deferred {
  let resolve = () => {};
  const promise = new Promise<void>((done) => {
    resolve = done;
  });
  return { promise, resolve };
}

function hexToRgb(value: string): Rgb {
  const hex = value.trim().replace(/^#/, "");
  const expanded =
    hex.length === 3
      ? hex
          .split("")
          .map((character) => `${character}${character}`)
          .join("")
      : hex;
  const parsed = Number.parseInt(expanded, 16);

  if (expanded.length !== 6 || Number.isNaN(parsed)) return [1, 1, 1];

  return [((parsed >> 16) & 255) / 255, ((parsed >> 8) & 255) / 255, (parsed & 255) / 255];
}

function resolvePalette(palette: ShaderSweepPaletteName | ShaderSweepPalette): ResolvedPalette {
  const colors = typeof palette === "string" ? SHADER_SWEEP_PALETTES[palette] : palette;
  return [hexToRgb(colors[0]), hexToRgb(colors[1]), hexToRgb(colors[2])];
}

function resolveDirection(direction: ShaderSweepDirection) {
  return {
    vertical: direction === "up" || direction === "down" ? 1 : 0,
    reverse: direction === "left" || direction === "up" ? 1 : 0,
  };
}

function resolveEasing(easing: ShaderSweepEasing) {
  if (typeof easing === "function") return easing;
  if (easing === "linear") return (progress: number) => progress;
  if (easing === "ease-out") return (progress: number) => 1 - (1 - progress) ** 4;
  return (progress: number) =>
    progress < 0.5 ? 4 * progress * progress * progress : 1 - Math.pow(-2 * progress + 2, 3) / 2;
}

function compileShader(
  gl: WebGLRenderingContext,
  type: number,
  source: string,
): WebGLShader | null {
  const shader = gl.createShader(type);
  if (!shader) return null;

  gl.shaderSource(shader, source);
  gl.compileShader(shader);

  if (gl.getShaderParameter(shader, gl.COMPILE_STATUS)) return shader;

  gl.deleteShader(shader);
  return null;
}

function createShaderRenderer(canvas: HTMLCanvasElement): ShaderRenderer | null {
  const gl = canvas.getContext("webgl", {
    alpha: true,
    antialias: false,
    premultipliedAlpha: true,
  });
  if (!gl) return null;

  const vertexShader = compileShader(gl, gl.VERTEX_SHADER, VERTEX_SHADER);
  const fragmentShader = compileShader(gl, gl.FRAGMENT_SHADER, FRAGMENT_SHADER);
  if (!vertexShader || !fragmentShader) {
    if (vertexShader) gl.deleteShader(vertexShader);
    if (fragmentShader) gl.deleteShader(fragmentShader);
    return null;
  }

  const program = gl.createProgram();
  if (!program) {
    gl.deleteShader(vertexShader);
    gl.deleteShader(fragmentShader);
    return null;
  }

  gl.attachShader(program, vertexShader);
  gl.attachShader(program, fragmentShader);
  gl.linkProgram(program);

  if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
    gl.deleteProgram(program);
    gl.deleteShader(vertexShader);
    gl.deleteShader(fragmentShader);
    return null;
  }

  gl.useProgram(program);

  const buffer = gl.createBuffer();
  if (!buffer) {
    gl.deleteProgram(program);
    gl.deleteShader(vertexShader);
    gl.deleteShader(fragmentShader);
    return null;
  }

  gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
  gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 1, -1, -1, 1, 1, 1]), gl.STATIC_DRAW);

  const position = gl.getAttribLocation(program, "aPosition");
  gl.enableVertexAttribArray(position);
  gl.vertexAttribPointer(position, 2, gl.FLOAT, false, 0, 0);

  const uniforms = {
    resolution: gl.getUniformLocation(program, "uResolution"),
    time: gl.getUniformLocation(program, "uTime"),
    progress: gl.getUniformLocation(program, "uProgress"),
    opacity: gl.getUniformLocation(program, "uOpacity"),
    vertical: gl.getUniformLocation(program, "uVertical"),
    reverse: gl.getUniformLocation(program, "uReverse"),
    bandSize: gl.getUniformLocation(program, "uBandSize"),
    intensity: gl.getUniformLocation(program, "uIntensity"),
    ripple: gl.getUniformLocation(program, "uRipple"),
    colorA: gl.getUniformLocation(program, "uColorA"),
    colorB: gl.getUniformLocation(program, "uColorB"),
    colorC: gl.getUniformLocation(program, "uColorC"),
  };

  gl.disable(gl.DEPTH_TEST);
  gl.enable(gl.BLEND);
  gl.blendFunc(gl.ONE, gl.ONE_MINUS_SRC_ALPHA);

  const resize = () => {
    const bounds = canvas.getBoundingClientRect();
    const pixelRatio = Math.min(window.devicePixelRatio || 1, 2);
    const width = Math.max(1, Math.round(bounds.width * pixelRatio));
    const height = Math.max(1, Math.round(bounds.height * pixelRatio));

    if (canvas.width === width && canvas.height === height) return;

    canvas.width = width;
    canvas.height = height;
    gl.viewport(0, 0, width, height);
  };

  resize();
  const resizeObserver = typeof ResizeObserver === "undefined" ? null : new ResizeObserver(resize);
  resizeObserver?.observe(canvas);

  const render = (frame: ShaderFrame) => {
    resize();
    gl.useProgram(program);
    gl.clearColor(0, 0, 0, 0);
    gl.clear(gl.COLOR_BUFFER_BIT);

    gl.uniform2f(uniforms.resolution, canvas.width, canvas.height);
    gl.uniform1f(uniforms.time, frame.time);
    gl.uniform1f(uniforms.progress, frame.progress);
    gl.uniform1f(uniforms.opacity, frame.opacity);
    gl.uniform1f(uniforms.vertical, frame.vertical);
    gl.uniform1f(uniforms.reverse, frame.reverse);
    gl.uniform1f(uniforms.bandSize, frame.bandSize);
    gl.uniform1f(uniforms.intensity, frame.intensity);
    gl.uniform1f(uniforms.ripple, frame.ripple);
    gl.uniform3f(uniforms.colorA, frame.palette[0][0], frame.palette[0][1], frame.palette[0][2]);
    gl.uniform3f(uniforms.colorB, frame.palette[1][0], frame.palette[1][1], frame.palette[1][2]);
    gl.uniform3f(uniforms.colorC, frame.palette[2][0], frame.palette[2][1], frame.palette[2][2]);
    gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);
  };

  return {
    render,
    clear: () => {
      gl.clearColor(0, 0, 0, 0);
      gl.clear(gl.COLOR_BUFFER_BIT);
    },
    destroy: () => {
      resizeObserver?.disconnect();
      gl.deleteBuffer(buffer);
      gl.deleteProgram(program);
      gl.deleteShader(vertexShader);
      gl.deleteShader(fragmentShader);
    },
  };
}

function createImmediatePlayback(options: ShaderSweepPlayOptions): ShaderSweepPlayback {
  const midpoint = Promise.resolve()
    .then(() => options.onMidpoint?.())
    .then(() => {});
  const finished = midpoint.then(() => options.onComplete?.());

  return {
    midpoint,
    finished,
    cancel: () => {},
  };
}

const ShaderSweep = forwardRef<ShaderSweepHandle, ShaderSweepProps>(
  (
    {
      palette = DEFAULT_OPTIONS.palette,
      direction = DEFAULT_OPTIONS.direction,
      duration = DEFAULT_OPTIONS.duration,
      fadeDuration = DEFAULT_OPTIONS.fadeDuration,
      midpoint = DEFAULT_OPTIONS.midpoint,
      bandSize = DEFAULT_OPTIONS.bandSize,
      intensity = DEFAULT_OPTIONS.intensity,
      ripple = DEFAULT_OPTIONS.ripple,
      easing = DEFAULT_OPTIONS.easing,
      onMidpoint,
      onComplete,
      position = "fixed",
      zIndex = 50,
      reducedMotion = "skip",
      className,
      style,
      ...props
    },
    forwardedRef,
  ) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const rendererRef = useRef<ShaderRenderer | null>(null);
    const activeRef = useRef<ShaderSweepPlayback | null>(null);
    const defaultsRef = useRef<ShaderSweepPlayOptions>({
      palette,
      direction,
      duration,
      fadeDuration,
      midpoint,
      bandSize,
      intensity,
      ripple,
      easing,
      onMidpoint,
      onComplete,
    });

    useEffect(() => {
      defaultsRef.current = {
        palette,
        direction,
        duration,
        fadeDuration,
        midpoint,
        bandSize,
        intensity,
        ripple,
        easing,
        onMidpoint,
        onComplete,
      };
    }, [
      bandSize,
      direction,
      duration,
      easing,
      fadeDuration,
      intensity,
      midpoint,
      onComplete,
      onMidpoint,
      palette,
      ripple,
    ]);

    const ensureRenderer = useCallback(() => {
      if (rendererRef.current) return rendererRef.current;
      if (!canvasRef.current) return null;

      rendererRef.current = createShaderRenderer(canvasRef.current);
      return rendererRef.current;
    }, []);

    const cancel = useCallback(() => {
      activeRef.current?.cancel();
      activeRef.current = null;
    }, []);

    const play = useCallback(
      (overrides: ShaderSweepPlayOptions = {}): ShaderSweepPlayback => {
        const options = { ...defaultsRef.current, ...overrides };
        const canvas = canvasRef.current;
        const shouldSkip =
          reducedMotion !== "animate" &&
          typeof window !== "undefined" &&
          window.matchMedia?.("(prefers-reduced-motion: reduce)").matches;

        activeRef.current?.cancel();

        if (!canvas || shouldSkip) {
          const immediate = createImmediatePlayback(options);
          activeRef.current = immediate;
          void immediate.finished.finally(() => {
            if (activeRef.current === immediate) activeRef.current = null;
          });
          return immediate;
        }

        const renderer = ensureRenderer();
        if (!renderer) {
          const immediate = createImmediatePlayback(options);
          activeRef.current = immediate;
          void immediate.finished.finally(() => {
            if (activeRef.current === immediate) activeRef.current = null;
          });
          return immediate;
        }

        const resolvedPalette = resolvePalette(options.palette ?? DEFAULT_OPTIONS.palette);
        const resolvedDirection = resolveDirection(options.direction ?? DEFAULT_OPTIONS.direction);
        const resolvedDuration = Math.max(80, options.duration ?? DEFAULT_OPTIONS.duration);
        const resolvedFadeDuration = Math.max(
          0,
          options.fadeDuration ?? DEFAULT_OPTIONS.fadeDuration,
        );
        const resolvedMidpoint = clamp(options.midpoint ?? DEFAULT_OPTIONS.midpoint, 0, 1);
        const resolvedBandSize = clamp(options.bandSize ?? DEFAULT_OPTIONS.bandSize, 0.035, 0.45);
        const resolvedIntensity = clamp(options.intensity ?? DEFAULT_OPTIONS.intensity, 0, 1.5);
        const resolvedRipple = clamp(options.ripple ?? DEFAULT_OPTIONS.ripple, 0, 1.5);
        const resolvedEasing = resolveEasing(options.easing ?? DEFAULT_OPTIONS.easing);
        const midpointDeferred = createDeferred();
        const finishedDeferred = createDeferred();

        let cancelled = false;
        let settled = false;
        let midpointFired = false;
        let animationFrame = 0;
        let releasePhase: (() => void) | null = null;
        let midpointTask: Promise<void> = Promise.resolve();
        const startedAt = performance.now();

        const renderFrame = (progress: number, opacity: number) => {
          renderer.render({
            progress,
            opacity,
            time: (performance.now() - startedAt) / 1000,
            vertical: resolvedDirection.vertical,
            reverse: resolvedDirection.reverse,
            bandSize: resolvedBandSize,
            intensity: resolvedIntensity,
            ripple: resolvedRipple,
            palette: resolvedPalette,
          });
        };

        const fireMidpoint = () => {
          if (midpointFired || cancelled) return;
          midpointFired = true;
          midpointTask = Promise.resolve()
            .then(() => options.onMidpoint?.())
            .catch(() => {})
            .then(() => midpointDeferred.resolve());
        };

        const animate = (
          phaseDuration: number,
          update: (rawProgress: number) => void,
        ): Promise<void> =>
          new Promise((resolve) => {
            const phaseStartedAt = performance.now();
            releasePhase = resolve;

            const tick = (now: number) => {
              if (cancelled) {
                releasePhase = null;
                resolve();
                return;
              }

              const rawProgress =
                phaseDuration === 0 ? 1 : clamp((now - phaseStartedAt) / phaseDuration, 0, 1);
              update(rawProgress);

              if (rawProgress < 1) {
                animationFrame = requestAnimationFrame(tick);
                return;
              }

              releasePhase = null;
              resolve();
            };

            animationFrame = requestAnimationFrame(tick);
          });

        const playback: ShaderSweepPlayback = {
          midpoint: midpointDeferred.promise,
          finished: finishedDeferred.promise,
          cancel: () => {
            if (settled) return;
            cancelled = true;
            settled = true;
            cancelAnimationFrame(animationFrame);
            releasePhase?.();
            releasePhase = null;
            renderer.clear();
            canvas.dataset.state = "idle";
            midpointDeferred.resolve();
            finishedDeferred.resolve();
          },
        };

        activeRef.current = playback;
        canvas.dataset.state = "running";

        void (async () => {
          await animate(resolvedDuration, (rawProgress) => {
            const easedProgress = clamp(resolvedEasing(rawProgress), 0, 1);
            renderFrame(easedProgress, 1);
            if (easedProgress >= resolvedMidpoint) fireMidpoint();
          });

          if (cancelled) return;
          fireMidpoint();
          await midpointTask;
          if (cancelled) return;

          await animate(resolvedFadeDuration, (rawProgress) => {
            const easedFade = rawProgress * rawProgress * (3 - 2 * rawProgress);
            renderFrame(1, 1 - easedFade);
          });

          if (cancelled) return;

          settled = true;
          renderer.clear();
          canvas.dataset.state = "idle";
          options.onComplete?.();
          finishedDeferred.resolve();

          if (activeRef.current === playback) activeRef.current = null;
        })();

        return playback;
      },
      [ensureRenderer, reducedMotion],
    );

    useImperativeHandle(forwardedRef, () => ({ play, cancel }), [cancel, play]);

    useEffect(
      () => () => {
        activeRef.current?.cancel();
        rendererRef.current?.destroy();
        rendererRef.current = null;
      },
      [],
    );

    return (
      <canvas
        {...props}
        ref={canvasRef}
        aria-hidden="true"
        data-shader-sweep=""
        data-state="idle"
        className={cn(
          "pointer-events-none inset-0 block size-full",
          position === "fixed" ? "fixed" : "absolute",
          className,
        )}
        style={{ zIndex, ...style }}
      />
    );
  },
);

ShaderSweep.displayName = "ShaderSweep";

export { SHADER_SWEEP_PALETTES, ShaderSweep };
export type {
  ShaderSweepDirection,
  ShaderSweepEasing,
  ShaderSweepHandle,
  ShaderSweepPalette,
  ShaderSweepPaletteName,
  ShaderSweepPlayback,
  ShaderSweepPlayOptions,
  ShaderSweepPosition,
  ShaderSweepProps,
};
